class Solution(object):
    def possibleToStamp(self, grid, stampHeight, stampWidth):
        """
        :type grid: List[List[int]]
        :type stampHeight: int
        :type stampWidth: int
        :rtype: bool
        """
        # ============================
        # pre-process
        # ============================
        M = len(grid)
        N = len(grid[0])

        # prefix sum for fast empty-region check
        presum = [[0] * (N + 1) for _ in range(M + 1)]
        for x in range(M):
            for y in range(N):
                presum[x + 1][y + 1] = (
                        presum[x][y + 1]
                        + presum[x + 1][y]
                        - presum[x][y]
                        + grid[x][y]
                )

        # check if region [sx..ex][sy..ey] contains only zeros
        def canStamp(sx, sy, ex, ey):
            total = (
                    presum[ex + 1][ey + 1]
                    - presum[sx][ey + 1]
                    - presum[ex + 1][sy]
                    + presum[sx][sy]
            )
            return total == 0

        # ============================
        # process
        # ============================

        from sortedcontainers import SortedList
        unvisited = SortedList(
            (x, y) for x in range(M) for y in range(N) if grid[x][y] == 0
        )

        failed = set()

        while unvisited:
            x, y = unvisited[0]  # smallest unvisited empty cell
            covered = False

            # four possible stamp placements that could cover (x, y)
            candidates = [
                (x, y),  # top-left corner
                (x, y - (stampWidth - 1)),  # top-right corner
                (x - (stampHeight - 1), y),  # bottom-left corner
                (x - (stampHeight - 1), y - (stampWidth - 1))  # bottom-right corner
            ]

            for sx, sy in candidates:
                ex = sx + stampHeight - 1
                ey = sy + stampWidth - 1

                # check bounds
                if sx < 0 or sy < 0 or ex >= M or ey >= N:
                    continue

                # check if stamp area is fully empty
                if canStamp(sx, sy, ex, ey):

                    # compute the earliest row/col that still matters
                    if unvisited:
                        min_un_x, min_un_y = unvisited[0]
                    else:
                        min_un_x, min_un_y = M, N

                    if failed:
                        min_fail_x = min(px for px, _ in failed)
                        min_fail_y = min(py for _, py in failed)
                    else:
                        min_fail_x, min_fail_y = M, N

                    min_row_of_interest = min(min_un_x, min_fail_x)
                    min_col_of_interest = min(min_un_y, min_fail_y)

                    # rows >= min_row_of_interest and cols >= min_col_of_interest
                    start_row = max(sx, min_row_of_interest)
                    start_col = max(sy, min_col_of_interest)

                    to_remove = []
                    for px in range(start_row, ex + 1):
                        for py in range(start_col, ey + 1):
                            if grid[px][py] == 0:
                                to_remove.append((px, py))

                    # remove from unvisited
                    for cell in to_remove:
                        unvisited.discard(cell)

                    # remove from failed
                    for cell in to_remove:
                        failed.discard(cell)

                    covered = True
                    break

            if not covered:
                # mark this cell as failed
                failed.add((x, y))
                # remove from unvisited
                unvisited.pop(0)
                continue

        # ============================
        # final decision
        # ============================
        return len(unvisited) == 0 and len(failed) == 0


